import React from "react";

export default function StoreCard({ store, onRateClick, myRating }) {
  return (
    <div className="bg-white rounded-lg shadow-md p-5 flex flex-col justify-between hover:shadow-lg transition">
      <div>
        <h3 className="text-xl font-bold text-gray-800 mb-2">{store.name}</h3>
        <p className="text-gray-600 text-sm mb-3">
          <span className="font-semibold">Address:</span> {store.address}
        </p>
      </div>

      <div className="mt-4 border-t pt-3">
        <div className="flex justify-between items-center mb-2">
          <span className="text-sm font-medium text-gray-500">Avg Rating:</span>
          <span className="text-lg font-bold text-yellow-600">{store.averageRating} ★ <span className="text-xs text-gray-400 font-normal">({store.totalRatings})</span></span>
        </div>
        <div className="flex justify-between items-center mb-4">
          <span className="text-sm font-medium text-gray-500">Your Rating:</span>
          <span className={`text-sm font-bold ${myRating ? 'text-blue-600' : 'text-gray-400'}`}>
            {myRating ? `${myRating.value} ★` : "Not Rated"}
          </span>
        </div>

        <button
          onClick={() => onRateClick(store)}
          className="w-full bg-indigo-600 text-white py-2 rounded-md font-medium hover:bg-indigo-700 transition"
        >
          {myRating ? "Edit Rating" : "Rate Store"}
        </button>
      </div>
    </div>
  );
}
